frappe.web_form.after_load = () => {
    setTimeout(() => {
        initializeAllChildTables();
    }, 300); // Reduced from 500ms
};

// ==================== INITIALIZE ALL CHILD TABLES ====================
function initializeAllChildTables() {
    let childTableFields = [];

    Object.keys(frappe.web_form.fields_dict).forEach(fieldname => {
        let field = frappe.web_form.fields_dict[fieldname];
        if (field && field.grid && field.grid.wrapper) {
            childTableFields.push({
                fieldname: fieldname,
                grid_field: field
            });
        }
    });

    childTableFields.forEach(({ fieldname, grid_field }) => {
        initializeChildTable(fieldname, grid_field);
    });
}

// ==================== HELPER FUNCTIONS ====================
function evaluateExpression(expression, doc) {
    if (!expression) return false;

    try {
        let cleanExpression = expression.trim();
        if (cleanExpression.startsWith("eval:")) {
            cleanExpression = cleanExpression.substring(5).trim();
        }

        const evalFunc = new Function('doc', `
            with(doc) {
                try {
                    return ${cleanExpression};
                } catch(e) {
                    return false;
                }
            }
        `);

        return evalFunc(doc);
    } catch (error) {
        return false;
    }
}

function isFieldHidden(field, doc) {
    if (field.hidden) return true;
    if (field.depends_on) {
        return !evaluateExpression(field.depends_on, doc);
    }
    return false;
}

function isFieldRequired(field, doc) {
    if (field.reqd) return true;
    if (field.mandatory_depends_on) {
        return evaluateExpression(field.mandatory_depends_on, doc);
    }
    return false;
}

// ==================== INITIALIZE CHILD TABLE ====================
function initializeChildTable(fieldname, grid_field) {
    if (!grid_field || !grid_field.grid) {
        return;
    }

    // Keep all rows collapsed
    if (grid_field.grid.grid_rows) {
        grid_field.grid.grid_rows.forEach(function(grid_row) {
            if (grid_row.doc && grid_row.wrapper) {
                grid_row.toggle_view(false);
            }
        });
    }

    // Override add_new_row
    let original_add_new_row = grid_field.grid.add_new_row.bind(grid_field.grid);
    grid_field.grid.add_new_row = function(idx, callback, show_dialog) {
        if (this.grid_rows) {
            this.grid_rows.forEach(function(row) {
                if (row.doc && row.wrapper) {
                    row.toggle_view(false);
                }
            });
        }

        let new_row = original_add_new_row(idx, callback, false);

        setTimeout(() => {
            let new_grid_row = this.grid_rows[this.grid_rows.length - 1];
            if (new_grid_row) {
                openCustomDialog(new_grid_row, this.grid_rows.length, fieldname);
            }
        }, 50); // Reduced timeout

        return new_row;
    };

    // Add click handler for existing rows
    $(grid_field.grid.wrapper).off('click.custom-grid').on('click.custom-grid', '.grid-row', function(e) {
        if ($(e.target).is('input[type="checkbox"]') || $(e.target).closest('.grid-row-check, .btn').length) {
            return;
        }

        let $row = $(this);
        let row_index = $row.index();
        let grid_row = grid_field.grid.grid_rows[row_index];

        if (grid_row) {
            openCustomDialog(grid_row, row_index + 1, fieldname);
        }
    });

    // Add edit icons
    addEditIcons(grid_field);

    // Set up observer for new rows
    if (grid_field.grid.wrapper) {
        try {
            let wrapperElement = grid_field.grid.wrapper;
            if (wrapperElement instanceof jQuery) {
                wrapperElement = wrapperElement[0];
            }

            if (wrapperElement && wrapperElement instanceof Node) {
                const observer = new MutationObserver(() => {
                    addEditIcons(grid_field);
                });

                observer.observe(wrapperElement, {
                    childList: true,
                    subtree: true
                });
            }
        } catch (error) {
            // Silent fallback
        }
    }
}

// ==================== CUSTOM DIALOG ====================
function openCustomDialog(grid_row, row_number, fieldname) {
    // Create modal
    let overlay = $('<div class="custom-grid-modal-overlay"></div>');
    let modal = $(`
        <div class="custom-grid-modal">
            <div class="custom-grid-modal-header">
                <h3>Row #${row_number}</h3>
                <button class="custom-modal-close" title="Close">&times;</button>
            </div>
            <div class="custom-grid-modal-body"></div>
            <div class="custom-grid-modal-footer">
                <button class="btn btn-secondary custom-modal-cancel">Cancel</button>
                <button class="btn btn-primary custom-modal-save">Save</button>
            </div>
        </div>
    `);

    overlay.append(modal);
    $('body').append(overlay);

    let fields = grid_row.grid.docfields || grid_row.grid.fields;
    let modalBody = modal.find('.custom-grid-modal-body');
    let currentDoc = { ...grid_row.doc };

    // Update field visibility and requirements
    function updateFieldStates() {
        fields.forEach(field => {
            if (field.fieldname === 'name') return;

            let fieldWrapper = modalBody.find(`[data-fieldname="${field.fieldname}"]`);
            if (fieldWrapper.length === 0) return;

            let shouldHide = isFieldHidden(field, currentDoc);
            let shouldBeRequired = isFieldRequired(field, currentDoc);

            if (shouldHide) {
                fieldWrapper.hide();
            } else {
                fieldWrapper.show();
            }

            let input = fieldWrapper.find('input, textarea, select, .file-upload-wrapper').first();
            let label = fieldWrapper.find('.custom-modal-label');

            if (shouldBeRequired) {
                input.attr('required', 'required');
                if (!label.find('.text-danger').length) {
                    label.append('<span class="text-danger">*</span>');
                }
            } else {
                input.removeAttr('required');
                label.find('.text-danger').remove();
            }
        });
    }

    // Create form fields
    fields.forEach(field => {
        if (field.fieldname === 'name' || field.hidden) return;

        let fieldWrapper = $(`
            <div class="custom-modal-field" data-fieldname="${field.fieldname}">
                <label class="custom-modal-label">
                    ${field.label}
                    ${field.reqd ? '<span class="text-danger">*</span>' : ''}
                </label>
                ${field.description ? `<div class="custom-modal-description">${field.description}</div>` : ''}
                <div class="custom-modal-input-wrapper"></div>
                <div class="custom-modal-error"></div>
            </div>
        `);

        let inputWrapper = fieldWrapper.find('.custom-modal-input-wrapper');
        let input;
        let fieldValue = grid_row.doc[field.fieldname];

        switch(field.fieldtype) {
            case 'Data':
            case 'Text':
                input = $(`<input type="text" class="form-control" placeholder="${field.label}">`);
                input.val(fieldValue || '');
                break;

            case 'Small Text':
                input = $(`<textarea class="form-control" rows="3" placeholder="${field.label}"></textarea>`);
                input.val(fieldValue || '');
                break;

            case 'Long Text':
                input = $(`<textarea class="form-control" rows="5" placeholder="${field.label}"></textarea>`);
                input.val(fieldValue || '');
                break;

            case 'Text Editor':
                input = $(`<textarea class="form-control text-editor-field" rows="6" placeholder="${field.label}"></textarea>`);
                input.val(fieldValue || '');
                fieldWrapper.addClass('custom-modal-field-editor');
                break;

            case 'Int':
            case 'Float':
            case 'Currency':
                input = $(`<input type="number" step="any" class="form-control" placeholder="${field.label}">`);
                input.val(fieldValue !== undefined && fieldValue !== null && fieldValue !== '' ? fieldValue : (field.default || ''));
                break;

            case 'Date':
                input = $(`<input type="date" class="form-control">`);
                input.val(fieldValue || '');
                break;

            case 'Datetime':
                input = $(`<input type="datetime-local" class="form-control">`);
                input.val(fieldValue || '');
                break;

            case 'Time':
                input = $(`<input type="time" class="form-control">`);
                input.val(fieldValue || '');
                break;

            case 'Select':
                input = $(`<select class="form-control"></select>`);
                let options = (field.options || '').split('\n');
                input.append('<option value=""></option>');
                options.forEach(opt => {
                    opt = opt.trim();
                    if (opt) {
                        input.append(`<option value="${opt}">${opt}</option>`);
                    }
                });
                input.val(fieldValue || '');
                break;

            case 'Check':
                input = $(`<input type="checkbox" class="form-check-input">`);
                let isChecked = (fieldValue === 1 || fieldValue === true || fieldValue === '1');
                input.prop('checked', isChecked);
                fieldWrapper.addClass('custom-modal-field-checkbox');
                break;

            case 'Link':
                input = $(`<input type="text" class="form-control" placeholder="${field.label}">`);
                input.val(fieldValue || '');
                break;

            case 'Attach':
            case 'Attach Image':
                let fileWrapper = $('<div class="file-upload-wrapper"></div>');

                let uploadBtn = $(`
                    <button type="button" class="btn btn-default btn-sm" style="width: 100%;">
                        <svg width="16" height="16" viewBox="0 0 16 16" fill="none" style="display: inline-block; margin-right: 6px; vertical-align: middle;">
                            <path d="M8 2v12M2 8h12" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
                        </svg>
                        <span>Choose File</span>
                    </button>
                `);

                let fileDisplay = $('<div class="file-display" style="margin-top: 8px;"></div>');

                if (fieldValue) {
                    fileWrapper.data('file-url', fieldValue);
                }

                function updateFileDisplay(fileUrl, fileName) {
                    if (fileUrl) {
                        fileDisplay.html(`
                            <div style="display: flex; align-items: center; gap: 8px; padding: 10px; background: #f9fafb; border: 1px solid #d1d5db; border-radius: 6px;">
                                <svg width="16" height="16" viewBox="0 0 16 16" fill="currentColor" style="flex-shrink: 0;">
                                    <path d="M9 1H4a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2V6l-5-5z"/>
                                    <path d="M9 1v4a1 1 0 001 1h4"/>
                                </svg>
                                <span style="flex: 1; font-size: 14px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${fileName}">${fileName}</span>
                                <a href="${fileUrl}" target="_blank" class="btn btn-xs btn-default" title="View">
                                    <svg width="12" height="12" viewBox="0 0 16 16" fill="currentColor">
                                        <path d="M8 3.5a4.5 4.5 0 100 9 4.5 4.5 0 000-9zM1 8a7 7 0 1114 0A7 7 0 011 8z"/>
                                    </svg>
                                </a>
                                <button type="button" class="btn btn-xs btn-danger" title="Remove">×</button>
                            </div>
                        `);
                        uploadBtn.hide();
                        fileDisplay.show();

                        // Attach remove handler
                        fileDisplay.find('.btn-danger').on('click', function(e) {
                            e.preventDefault();
                            fileWrapper.data('file-url', '');
                            currentDoc[field.fieldname] = '';
                            updateFileDisplay('', '');
                            updateFieldStates();
                        });
                    } else {
                        fileDisplay.empty().hide();
                        uploadBtn.show();
                    }
                }

                if (fieldValue) {
                    let fileName = fieldValue.split('/').pop();
                    updateFileDisplay(fieldValue, fileName);
                }

                uploadBtn.on('click', function() {
                    new frappe.ui.FileUploader({
                        make_attachments_public: false,
                        restrictions: {
                            allowed_file_types: field.fieldtype === 'Attach Image' ? ['image/*'] : []
                        },
                        on_success: function(file_doc) {
                            fileWrapper.data('file-url', file_doc.file_url);
                            currentDoc[field.fieldname] = file_doc.file_url;
                            updateFileDisplay(file_doc.file_url, file_doc.file_name);
                            updateFieldStates();

                            frappe.show_alert({
                                message: 'File uploaded',
                                indicator: 'green'
                            }, 2);
                        }
                    });
                });

                fileWrapper.append(uploadBtn);
                fileWrapper.append(fileDisplay);
                input = fileWrapper;
                fieldWrapper.addClass('custom-modal-field-file');
                break;

            default:
                input = $(`<input type="text" class="form-control" placeholder="${field.label}">`);
                input.val(fieldValue || '');
        }

        if (field.reqd && field.fieldtype !== 'Attach' && field.fieldtype !== 'Attach Image') {
            input.attr('required', 'required');
        }

        input.data('field', field);
        input.data('fieldname', field.fieldname);

        // Add change listener (except for file fields)
        if (field.fieldtype !== 'Attach' && field.fieldtype !== 'Attach Image') {
            input.on('change input', function() {
                let fname = $(this).data('fieldname');
                let fld = $(this).data('field');

                if (fld.fieldtype === 'Check') {
                    currentDoc[fname] = $(this).prop('checked') ? 1 : 0;
                } else if (['Int', 'Float', 'Currency'].includes(fld.fieldtype)) {
                    let val = $(this).val();
                    currentDoc[fname] = val !== '' ? parseFloat(val) || 0 : 0;
                } else {
                    currentDoc[fname] = $(this).val();
                }

                updateFieldStates();
            });
        }

        inputWrapper.append(input);
        modalBody.append(fieldWrapper);
    });

    updateFieldStates();

    // Validation
    function validateForm() {
        let isValid = true;
        modal.find('.custom-modal-field:visible').each(function() {
            let fieldWrapper = $(this);
            let input = fieldWrapper.find('input, textarea, select').first();
            let field = input.data('field');
            let errorDiv = fieldWrapper.find('.custom-modal-error');

            errorDiv.text('').hide();
            input.removeClass('is-invalid');

            if (field && isFieldRequired(field, currentDoc)) {
                let value = input.val();

                if (field.fieldtype === 'Attach' || field.fieldtype === 'Attach Image') {
                    value = fieldWrapper.find('.file-upload-wrapper').data('file-url');
                } else if (field.fieldtype === 'Check') {
                    value = input.prop('checked') ? 1 : 0;
                }

                if (!value || value === '' || value === null) {
                    isValid = false;
                    input.addClass('is-invalid');
                    errorDiv.text(`${field.label} is required`).show();
                }
            }
        });

        return isValid;
    }

    // Save button
    modal.find('.custom-modal-save').on('click', function() {
        if (!validateForm()) {
            frappe.show_alert({
                message: 'Please fill all required fields',
                indicator: 'red'
            }, 3);
            return;
        }

        modal.find('.custom-modal-field:visible').each(function() {
            let fieldWrapper = $(this);
            let input = fieldWrapper.find('input, textarea, select, .file-upload-wrapper').first();
            let fieldname = input.data('fieldname');
            let field = input.data('field');

            if (fieldname && field) {
                if (field.fieldtype === 'Check') {
                    grid_row.doc[fieldname] = input.prop('checked') ? 1 : 0;
                } else if (['Int', 'Float', 'Currency'].includes(field.fieldtype)) {
                    let val = input.val();
                    grid_row.doc[fieldname] = val !== '' ? parseFloat(val) || 0 : 0;
                } else if (field.fieldtype === 'Attach' || field.fieldtype === 'Attach Image') {
                    let fileUrl = input.data('file-url');
                    grid_row.doc[fieldname] = fileUrl || '';
                } else {
                    grid_row.doc[fieldname] = input.val();
                }
            }
        });

        grid_row.refresh();
        overlay.remove();

        frappe.show_alert({
            message: 'Saved',
            indicator: 'green'
        }, 2);
    });

    // Cancel button
    modal.find('.custom-modal-cancel, .custom-modal-close').on('click', function() {
        let isEmpty = true;
        fields.forEach(field => {
            if (field.fieldname !== 'name' && grid_row.doc[field.fieldname]) {
                isEmpty = false;
            }
        });

        if (isEmpty) {
            grid_row.remove();
        }

        overlay.remove();
    });

    // Close on overlay click
    overlay.on('click', function(e) {
        if ($(e.target).hasClass('custom-grid-modal-overlay')) {
            modal.find('.custom-modal-cancel').click();
        }
    });

    // Focus first input
    setTimeout(() => {
        modal.find('.custom-modal-field:visible').first()
            .find('input, textarea, select').first().focus();
    }, 50);
}

// ==================== ADD EDIT ICONS ====================
function addEditIcons(grid_field) {
    if (!grid_field || !grid_field.grid || !grid_field.grid.wrapper) return;

    $(grid_field.grid.wrapper).find('.grid-row').each(function() {
        let $row = $(this);
        if (!$row.find('.custom-edit-icon').length) {
            let $icon = $('<span class="custom-edit-icon" title="Edit">✎</span>');
            $row.find('.data-row').append($icon);
        }
    });
}

